   metric=score(fields[key],ref,fields[maskkey],valid);checks[side+'_'+name+'_metrics']=matching(metric,receipt[receiptkey]);on_common=score(fields[key],ref,common,valid);checks[side+'_'+name+'_common_metrics']=matching(on_common,receipt['common_physical_grid'][name]);scores[name]={'full_overlap':metric,'common_overlap':on_common}
